DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.change_membership(uuid,boolean)'::regprocedure) INTO def; def:=replace(def,'IF _join THEN IF m.status=''active'' THEN','IF _join THEN IF m.status=''suspended'' THEN RAISE EXCEPTION ''Cette adhésion est suspendue''; END IF; IF m.status=''active'' THEN'); EXECUTE def; SELECT pg_get_functiondef('public.reserve_social_event(uuid)'::regprocedure) INTO def; def:=replace(def,'INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,organization_event_id','IF EXISTS(SELECT 1 FROM public.activities a WHERE a.character_id=cid AND a.source_key=''org:''||e.id||'':''||(start_at AT TIME ZONE ''UTC'')::date) THEN RAISE EXCEPTION ''Vous avez déjà réservé ce rendez-vous pour cette journée''; END IF; INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,organization_event_id'); EXECUTE def; SELECT pg_get_functiondef('public.social_interact(uuid,text)'::regprocedure) INTO def; def:=replace(def,'IF _action_id=''invite'' THEN start_at:=','IF _action_id=''invite'' THEN IF EXISTS(SELECT 1 FROM public.activities a WHERE a.character_id=cid AND a.source_key=''invite:''||n.id||'':''||(t AT TIME ZONE ''UTC'')::date) THEN RAISE EXCEPTION ''Une invitation a déjà été proposée à cette personne aujourd’hui''; END IF; start_at:='); EXECUTE def; END $$;